(26,	'INDIVIDUAL_2024',	'Individual and Dependent Relatives',	'Automatic relief for individual taxpayer and dependent relatives. No receipts required.',	9000.00,	NULL,	'2024',	'Official',	'2024-10-01',	NULL,	NULL,	'No',	'Self',	'Yearly',	1,	'Self',	'Yes',	'Active',	'2025-12-28 08:23:00',	'2025-12-28 08:23:00'),
(27,	'PARENT_MEDICAL_2024',	'Expenses for Parents',	'Medical treatment, dental treatment, special needs and carer expenses for parents. Medical condition must be certified by medical practitioner apply. Complete medical examination is limited to RM1,000.',	8000.00,	NULL,	'2024',	'Official',	'2024-10-01',	NULL,	NULL,	'Yes',	'Parent',	'Yearly',	2,	'Self',	'No',	'Active',	'2025-12-28 08:23:00',	'2025-12-28 08:23:00'),
