(30,	'EDUCATION_SELF_2024',	'Education Fees (Self)',	'Education fees for self. Includes courses in law, accounting, Islamic financing, technical, vocational, industrial, scientific or technology fields. Masters/Doctorate in any field. Upskilling courses limited to RM2,000.',	7000.00,	NULL,	'2024',	'Official',	'2024-10-01',	NULL,	NULL,	'Yes',	'Self',	'Yearly',	5,	'Self',	'No',	'Active',	'2025-12-28 08:23:00',	'2025-12-28 08:23:00'),
(31,	'MEDICAL_SERIOUS_2024',	'Medical Expenses (Serious Diseases & Others)',	'Medical expenses for serious diseases for self, spouse or child. Includes fertility treatment. Vaccination limited to RM1,000. Dental examination/treatment limited to RM1,000.',	10000.00,	NULL,	'2024',	'Official',	'2024-10-01',	NULL,	NULL,	'Yes',	'Self,Spouse,Child',	'Yearly',	6,	'Self',	'No',	'Active',	'2025-12-28 08:23:00',	'2025-12-28 08:23:00'),
(32,	'MEDICAL_EXAM_2024',	'Complete Medical Examination & Health Screening',	'Complete medical examination, COVID-19 detection test, mental health examination/consultation for self, spouse or child then examination or consultation for self, spouse, or child. Limited to RM1,000.',	1000.00,	NULL,	'2024',	'Official',	'2024-10-01',	NULL,	NULL,	'Yes',	'Self,Spouse,Child',	'Yearly',	7,	'Self',	'No',	'Active',	'2025-12-28 08:23:00',	'2025-12-28 08:23:00'),
